import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
    except StopIteration:
        return

    nodes = {}
    roots = []

    # Build the tree based on input format
    # Assuming input format: N followed by N lines of "parent left right"
    # If left or right is -1, it means no child
    # We need to identify the root (node that never appears as a child)

    children = set()

    for _ in range(n):
        parent_val = int(next(iterator))
        left_val = int(next(iterator))
        right_val = int(next(iterator))

        if parent_val not in nodes:
            nodes[parent_val] = Node(parent_val)

        parent_node = nodes[parent_val]

        if left_val != -1:
            if left_val not in nodes:
                nodes[left_val] = Node(left_val)
            parent_node.left = nodes[left_val]
            children.add(left_val)

        if right_val != -1:
            if right_val not in nodes:
                nodes[right_val] = Node(right_val)
            parent_node.right = nodes[right_val]
            children.add(right_val)

    # Find root
    root = None
    for val in nodes:
        if val not in children:
            root = nodes[val]
            break

    if root is None and nodes:
        # If there's only one node or all are disconnected, pick first
        root = next(iter(nodes.values()))

    result = inOrder(root)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
